import re
src = open('planb64.cpp').read()

# 1. Row struct: hop as uint32, no-match signalled by len == -1
src = src.replace('''struct Row {
    std::uint64_t start;
    std::int32_t hop;  // -1 when no route matches
    std::int32_t len;  // -1 when no route matches
};''', '''struct Row {
    std::uint64_t start;
    std::uint32_t hop;  // meaningful only when len >= 0
    std::int32_t len;   // -1 when no route matches
};''')

# 2. compile sweep winner
src = src.replace('''        std::int32_t hop = -1, len = -1;
        if (!stack.empty()) {
            hop = static_cast<std::int32_t>(stack.back().hop);
            len = static_cast<std::int32_t>(stack.back().len);
        }''', '''        std::uint32_t hop = 0;
        std::int32_t len = -1;
        if (!stack.empty()) {
            hop = stack.back().hop;
            len = static_cast<std::int32_t>(stack.back().len);
        }''')

# 3. image row parser: keep parsed values as int64, validate pair, store safely
src = src.replace('''    const std::int64_t hop = parse_image_field(hop_text, 4294967295ull, "next hop");
    const std::int64_t len = parse_image_field(len_text, 64, "prefix length");
    if ((hop < 0) != (len < 0)) fail("malformed image row pair");
    return Row{start, static_cast<std::int32_t>(hop),
               static_cast<std::int32_t>(len)};''', '''    const std::int64_t hop = parse_image_field(hop_text, 4294967295ull, "next hop");
    const std::int64_t len = parse_image_field(len_text, 64, "prefix length");
    if ((hop < 0) != (len < 0)) fail("malformed image row pair");
    return Row{start,
               hop < 0 ? 0u : static_cast<std::uint32_t>(hop),
               static_cast<std::int32_t>(len)};''')

# 4. emit_answers output
src = src.replace('''            const Row& r = rows[lo - 1];  // rows[0].start == 0, so lo >= 1
            append_dec(out, r.hop);
