                out.append("-1 -1\\n", 6);
            } else {
                append_dec(out, static_cast<std::int64_t>(r.hop));
                out.push_back(' ');
                append_dec(out, r.len);
                out.push_back('\\n');
            }''')

# 5. serialize_image output
src = src.replace('''        append_hex16(out, r.start);
        out.push_back(' ');
        append_dec(out, r.hop);
        out.push_back(' ');
        append_dec(out, r.len);
        out.push_back('\\n');''', '''        append_hex16(out, r.start);
